 final android.content.SharedPreferences.OnSharedPreferenceChangeListener dataListener=(p,k)->{if(k!=null&&(k.equals("tasks")||k.equals("canvasSync")||k.equals("canvasError")||k.equals("weatherUpdated")))runOnUiThread(()->{if(!isDestroyed()){load();if(foreground&&!busy&&!page.equals("assistant"))render();}});};
