 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=TaskStore.prefs(this);prefs.registerOnSharedPreferenceChangeListener(dataListener);load();if(b!=null){page=b.getString("page","today");date=LocalDate.parse(b.getString("date",date.toString()));}route(getIntent());if(!(this instanceof ChatActivity)&&prefs.getInt("seenVersion",0)<11)changelog();}
