 @Override protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);load();route(i);}
 void route(Intent i){String chosenDay=i.getStringExtra("date");if(chosenDay!=null)try{date=LocalDate.parse(chosenDay);}catch(Exception ignored){}String p=i.getStringExtra("page");if(p!=null&&Arrays.asList("today","week","month","calendar","timetable","assistant","settings").contains(p))page=p;render();String id=i.getStringExtra("task");if(id!=null&&!id.isEmpty()){JSONObject t=TaskStore.find(tasks,id);if(t!=null)edit(t,null);}else if(i.getBooleanExtra("add",false))edit(null,null);i.removeExtra("task");i.removeExtra("add");}
