  LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.saber_cat);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);logo.setBackground(Saber.shape(this,Saber.SURFACE,12,0));logo.setClipToOutline(true);top.addView(logo,new LinearLayout.LayoutParams(dp(38),dp(38)));TextView title=text("saber喵",23);title.setPadding(dp(10),dp(12),0,dp(12));title.setTypeface(null,Typeface.BOLD);top.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView version=text("1.1.5",12);version.setTextColor(Saber.GOLD);top.addView(version);root.addView(top);
  if(!page.equals("settings")){WeatherUi.strip(this,root);LinearLayout tabs=new LinearLayout(this);String[] names={"今天","未来7天","本月","日历","课表"},keys={"today","week","month","calendar","timetable"};for(int n=0;n<5;n++){final String k=keys[n];Button b=button(names[n],()->{page=k;date=LocalDate.now(Schedule.ZONE);render();});b.setTextSize(14);if(page.equals(k))b.setBackground(Saber.shape(this,Saber.BLUE,20,0));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(44),1);lp.setMargins(dp(2),dp(10),dp(2),dp(8));tabs.addView(b,lp);}root.addView(tabs);}
