  LinearLayout nav=new LinearLayout(this);String[] names={"日程","助手","设置"};for(int n=0;n<3;n++){final int item=n;Button b=button(names[n],()->{if(item==1){startActivity(new Intent(this,ChatActivity.class));return;}page=item==0?"today":"settings";render();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(54),1);lp.setMargins(dp(3),dp(6),dp(3),dp(5));nav.addView(b,lp);}root.addView(nav);Saber.floating(this,frame);final int restoreY=agendaY;scroll.post(()->scroll.scrollTo(0,restoreY));
