 List<JSONObject> onDate(LocalDate day){List<JSONObject> a=new ArrayList<>();for(JSONObject t:TaskStore.sorted(tasks))if(t.optString("due").equals(day.toString()))a.add(t);return a;}
 void focusSection(){LocalDate now=LocalDate.now(Schedule.ZONE);boolean header=false;for(JSONObject t:Agenda.ordered(tasks,now))if(Agenda.focus(t,now)){if(!header){body.addView(text("重点提醒",19));header=true;}taskCard(t);}}
 void normalTasks(List<JSONObject> list){for(boolean canvas:new boolean[]{false,true}){boolean header=false;for(JSONObject t:list)if(!Agenda.focus(t,LocalDate.now(Schedule.ZONE))&&Agenda.canvas(t)==canvas){if(!header){body.addView(text(canvas?"Canvas 作业":"其他待办",18));header=true;}taskCard(t);}}}
 void taskSection(boolean canvas,String scope,LocalDate view){List<JSONObject> list=Agenda.section(tasks,canvas,scope,view,LocalDate.now(Schedule.ZONE),true);body.addView(text(canvas?"Canvas 作业":"个人待办",19));if(list.isEmpty())body.addView(text("暂无待办",14));for(JSONObject t:list)taskCard(t);}
 void today(){LocalDate now=LocalDate.now(Schedule.ZONE);body.addView(text("今天 · "+now,21));body.addView(button("＋ 记一件事",()->edit(null,null)));taskSection(false,"today",now);body.addView(text("今日课程",19));showCourses(now,false);taskSection(true,"today",now);}
 void taskCard(JSONObject task){LinearLayout c=card();if(Agenda.focus(task,LocalDate.now(Schedule.ZONE))){TextView flag=text(Agenda.focusLabel(task,LocalDate.now(Schedule.ZONE)),14);flag.setTextColor(Saber.GOLD);c.addView(flag);}if(!task.optString("notes").isEmpty())c.addView(text("备注："+task.optString("notes"),14));CheckBox check=new CheckBox(this);check.setText(task.optString("title"));check.setTextSize(17);check.setTextColor(ink);check.setChecked(task.optBoolean("done"));if(check.isChecked())check.setPaintFlags(check.getPaintFlags()|Paint.STRIKE_THRU_TEXT_FLAG);c.addView(check);
  check.setOnCheckedChangeListener((v,done)->{try{TaskStore.patch(this,task.optString("id"),new JSONObject().put("done",done));load();render();}catch(Exception e){toast("保存失败");}});
  String due=task.optString("due"),detail=(due.isEmpty()?"未定日期":due+" "+task.optString("plannedTime"))+" · "+(task.optBoolean("estimateUnknown")?"耗时待估":task.optInt("minutes",30)+" 分钟");
  if(!task.optBoolean("done")&&!due.isEmpty()&&due.compareTo(LocalDate.now(Schedule.ZONE).toString())<0)detail="逾期 · "+detail;c.addView(text(detail,13));
  if(task.optBoolean("reminder"))c.addView(text("提醒 "+task.optString("reminderDate")+" "+task.optString("reminderTime")+(task.optBoolean("done")?" · 已取消":!Reminders.notifications(this)?" · 通知未开启":!Reminders.exact(this)?" · 可能延迟":""),13));
  if(task.optString("source").equals("canvas")){c.addView(text(task.optString("course")+" · Canvas "+(task.optBoolean("submitted")?"已提交 / 已评分":"未确认提交"),13));if(task.optBoolean("deadlineChanged"))c.addView(text("截止时间有变化，原提醒已关闭，请重新确认。",13));if(task.optBoolean("sourceMissing"))c.addView(text("最近同步未找到此作业，请到 Canvas 核对。",13));}
  LinearLayout actions=new LinearLayout(this);actions.addView(button("编辑 / 提醒",()->edit(task,null)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("创建闹钟",()->clock(task)),new LinearLayout.LayoutParams(0,-2,1));c.addView(actions);
 }
 void periodNav(String label,Runnable prev,Runnable next){LinearLayout row=new LinearLayout(this);row.addView(button("‹",prev),new LinearLayout.LayoutParams(0,-2,1));TextView t=text(label,18);t.setGravity(Gravity.CENTER);row.addView(t,new LinearLayout.LayoutParams(0,-2,4));row.addView(button("›",next),new LinearLayout.LayoutParams(0,-2,1));body.addView(row);}
 void week(){LocalDate start=LocalDate.now(Schedule.ZONE);date=start;body.addView(text("未来7天 · "+start+" — "+start.plusDays(6),19));body.addView(button("＋ 记一件事",()->edit(null,null)));taskSection(false,"week",date);
  body.addView(text("未来7天课程",19));for(int d=0;d<7;d++){LocalDate day=start.plusDays(d);LinearLayout header=card();header.addView(button(day+" "+weekday(day),()->{date=day;page="calendar";render();}));String classes=courseSummary(day);header.addView(text(classes.isEmpty()?"无课程":classes,13));}taskSection(true,"week",date);
 }
 String weekday(LocalDate d){return new String[]{"周一","周二","周三","周四","周五","周六","周日"}[d.getDayOfWeek().getValue()-1];}
 void month(){YearMonth ym=YearMonth.from(date);periodNav(ym.toString(),()->{date=date.minusMonths(1);render();},()->{date=date.plusMonths(1);render();});LinearLayout labels=new LinearLayout(this);for(String s:new String[]{"一","二","三","四","五","六","日"}){TextView t=text(s,14);t.setGravity(Gravity.CENTER);labels.addView(t,new LinearLayout.LayoutParams(0,-2,1));}body.addView(labels);
  int offset=ym.atDay(1).getDayOfWeek().getValue()-1,total=((offset+ym.lengthOfMonth()+6)/7)*7;LinearLayout row=null;
  for(int cell=0;cell<total;cell++){if(cell%7==0){row=new LinearLayout(this);body.addView(row);}int n=cell-offset+1;if(n<1||n>ym.lengthOfMonth()){row.addView(new TextView(this),new LinearLayout.LayoutParams(0,dp(58),1));continue;}LocalDate day=ym.atDay(n);String mark=Agenda.monthMark(tasks,courses,day,LocalDate.now(Schedule.ZONE));Button b=button(n+(mark.isEmpty()?"":"\n"+mark),()->{date=day;page="calendar";render();});b.setPadding(dp(1),0,dp(1),0);b.setTextSize(11);b.setMinHeight(0);b.setMinimumHeight(0);GradientDrawable tile=new GradientDrawable();tile.setCornerRadius(dp(9));tile.setColor(mark.contains("!")?0xff614c35:mark.contains("事")||mark.contains("作")?0xff244a7d:mark.contains("课")?0xff25554f:Saber.SURFACE);if(day.equals(LocalDate.now(Schedule.ZONE))){tile.setStroke(dp(2),blue);b.setTypeface(null,Typeface.BOLD);}b.setBackground(tile);b.setContentDescription(day+" "+mark);LinearLayout.LayoutParams cellParams=new LinearLayout.LayoutParams(0,dp(76),1);cellParams.setMargins(dp(1),dp(2),dp(1),dp(2));row.addView(b,cellParams);}


 }
 void calendar(){periodNav(date+" "+weekday(date),()->{date=date.minusDays(1);render();},()->{date=date.plusDays(1);render();});body.addView(button("选择日期",()->pickDate(date,d->{date=d;render();})));body.addView(button("＋ 当天待办",()->{try{edit(null,new JSONObject().put("due",date.toString()));}catch(Exception ignored){}}));focusSection();body.addView(text("当天课程",18));showCourses(date,false);List<JSONObject> list=onDate(date);for(JSONObject t:TaskStore.sorted(tasks))if(Agenda.canvas(t)&&Agenda.deadline(t)!=null&&Agenda.deadline(t).equals(date)&&!list.contains(t))list.add(t);normalTasks(list);}

 List<Schedule.Event> dayCourses(LocalDate day){List<Schedule.Event> list=new ArrayList<>();for(Schedule.Event e:courses)if(e.on(day))list.add(e);list.sort(Comparator.comparing(e->e.start.toLocalTime()));return list;}
 String courseSummary(LocalDate day){StringBuilder b=new StringBuilder();for(Schedule.Event e:dayCourses(day)){if(b.length()>0)b.append("\n");b.append(e.start.toLocalTime()).append(" ").append(e.title);}return b.toString();}
 void showCourses(LocalDate day,boolean unused){if(courses.isEmpty()){card().addView(text("设置中导入 WakeUp ICS 后显示课程。",15));return;}List<Schedule.Event> list=dayCourses(day);for(Schedule.Event e:list){LinearLayout c=card();c.addView(text(e.start.toLocalTime()+"—"+e.end.toLocalTime()+"  "+e.title,17));c.addView(text(CourseStatus.label(e,day,Instant.now())+" · "+e.location,13));}if(list.isEmpty())body.addView(text("当天无课程，请另行核对调休。",14));}
 interface DateChosen{void set(LocalDate d);}interface TimeChosen{void set(String s);}
 void pickDate(LocalDate initial,DateChosen f){new DatePickerDialog(this,(v,y,m,d)->f.set(LocalDate.of(y,m+1,d)),initial.getYear(),initial.getMonthValue()-1,initial.getDayOfMonth()).show();}
 void pickTime(String initial,TimeChosen f){LocalTime t;try{t=LocalTime.parse(initial);}catch(Exception e){t=LocalTime.now().plusMinutes(5);}new TimePickerDialog(this,(v,h,m)->f.set(String.format(Locale.ROOT,"%02d:%02d",h,m)),t.getHour(),t.getMinute(),true).show();}
 EditText field(LinearLayout form,String label,String value){form.addView(text(label,13));EditText e=new EditText(this);e.setText(value);e.setTextSize(16);e.setTextColor(ink);e.setHintTextColor(Saber.MUTED);e.setBackground(Saber.shape(this,Saber.BG,16,Saber.LINE));e.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.setMargins(0,0,0,dp(10));form.addView(e,fp);return e;}
 void edit(JSONObject existing,JSONObject draft){
  JSONObject base=existing!=null?existing:(draft!=null?draft:new JSONObject());LinearLayout form=column();form.setPadding(dp(18),dp(6),dp(18),dp(6));ScrollView scroll=new ScrollView(this);scroll.addView(form);
  EditText title=field(form,"事项",base.optString("title"));title.setSingleLine();EditText notes=field(form,"备注",base.optString("notes"));notes.setMinLines(2);CheckBox important=new CheckBox(this);important.setText("重点提醒");important.setTextColor(ink);important.setChecked(base.optBoolean("important"));if(!Agenda.canvas(base))form.addView(important);
  final String[] due={base.optString("due")},planTime={base.optString("plannedTime")},remDate={base.optString("reminderDate",base.optString("due",LocalDate.now(Schedule.ZONE).toString()))},remTime={base.optString("reminderTime","09:00")};
  Button day=button("计划日期："+(due[0].isEmpty()?"未定":due[0]),()->{});day.setOnClickListener(v->pickDate(due[0].isEmpty()?LocalDate.now(Schedule.ZONE):LocalDate.parse(due[0]),d->{due[0]=d.toString();day.setText("计划日期："+due[0]);}));form.addView(day);
  form.addView(button("清除计划日期",()->{due[0]="";day.setText("计划日期：未定");}));Button time=button("计划时间："+(planTime[0].isEmpty()?"未定":planTime[0]),()->{});time.setOnClickListener(v->pickTime(planTime[0],s->{planTime[0]=s;time.setText("计划时间："+s);}));form.addView(time);
  EditText minutes=field(form,"耗时 / 分钟",base.optString("minutes","30"));minutes.setInputType(2);
  CheckBox reminder=new CheckBox(this);reminder.setText("提醒这件待办");reminder.setTextColor(ink);reminder.setChecked(base.optBoolean("reminder"));form.addView(reminder);
  if(remDate[0].isEmpty())remDate[0]=LocalDate.now(Schedule.ZONE).toString();Button rd=button("提醒日期："+remDate[0],()->{});rd.setOnClickListener(v->pickDate(LocalDate.parse(remDate[0]),d->{remDate[0]=d.toString();rd.setText("提醒日期："+remDate[0]);}));form.addView(rd);rd.setVisibility(reminder.isChecked()?View.VISIBLE:View.GONE);Button rt=button("提醒时间："+remTime[0],()->{});rt.setOnClickListener(v->pickTime(remTime[0],s->{remTime[0]=s;rt.setText("提醒时间："+s);}));form.addView(rt);rt.setVisibility(reminder.isChecked()?View.VISIBLE:View.GONE);reminder.setOnCheckedChangeListener((v,on)->{rd.setVisibility(on?View.VISIBLE:View.GONE);rt.setVisibility(on?View.VISIBLE:View.GONE);});
  
  if(existing!=null){form.addView(button("用手机时钟创建闹钟",()->clock(existing)));if(existing.optString("source").equals("canvas")){form.addView(text("Canvas 截止："+existing.optString("canvasDue","未提供"),13));form.addView(button("查看 Canvas 作业",()->openWeb(existing.optString("url"))));form.addView(button("让 AI 估算作业耗时",()->{if(editingDialog!=null)editingDialog.dismiss();page="assistant";render();ask("请估算这项作业需要多久，给出范围、步骤、依据和不确定性。若描述不足请明确说明，不能仅凭分数推断。\n课程："+existing.optString("course")+"\n标题："+existing.optString("title")+"\n题目："+existing.optString("description"),false);}));}
  }
  AlertDialog.Builder builder=new UiDialog.Builder(this).setTitle(existing==null?"新增待办":"编辑待办").setView(scroll).setPositiveButton("保存",null).setNegativeButton("取消",null);
  if(existing!=null)builder.setNeutralButton("删除",(d,w)->new UiDialog.Builder(this).setMessage("删除这件待办？Canvas 作业在下次同步时可能重新导入。").setPositiveButton("删除",(a,b)->{TaskStore.delete(this,existing.optString("id"));load();render();}).setNegativeButton("取消",null).show());
  AlertDialog dialog=builder.create();editingDialog=dialog;dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{
   String name=title.getText().toString().trim();if(name.isEmpty()||name.length()>200)throw new IllegalArgumentException("事项名称需为 1–200 字");int length=Integer.parseInt(minutes.getText().toString());if(length<1||length>1440)throw new IllegalArgumentException("耗时应为 1–1440 分钟");
   long at=TaskDates.reminderMillis(remDate[0],remTime[0]);boolean changed=existing==null||TaskStore.at(existing)!=at||!existing.optBoolean("reminder");if(reminder.isChecked()&&changed&&at<=System.currentTimeMillis())throw new IllegalArgumentException("请选择未来的提醒时间");
   if(existing!=null&&Agenda.canvas(existing)){JSONObject latest=TaskStore.find(TaskStore.load(this),existing.optString("id"));if(latest==null||latest.optBoolean("archived")||!latest.optString("canvasDue").equals(existing.optString("canvasDue")))throw new IllegalArgumentException("作业状态或截止时间已更新，请关闭后重新打开编辑");}JSONObject t=new JSONObject();if(notes.getText().length()>5000)throw new IllegalArgumentException("备注最多 5000 字");t.put("notes",notes.getText().toString());t.put("important",important.isChecked());if(existing!=null&&existing.optString("source").equals("canvas")&&(!due[0].equals(existing.optString("due"))||!planTime[0].equals(existing.optString("plannedTime"))))t.put("dateCustomized",true);
   t.put("title",name);t.put("due",due[0]);t.put("plannedTime",planTime[0]);t.put("minutes",length);t.put("estimateUnknown",false);t.put("reminder",reminder.isChecked());t.put("reminderDate",remDate[0]);t.put("reminderTime",remTime[0]);t.put("deadlineChanged",false);
   if(existing==null){t.put("id",UUID.randomUUID().toString());t.put("done",false);TaskStore.add(this,t);}else TaskStore.patch(this,existing.optString("id"),t);load();dialog.dismiss();render();if(reminder.isChecked()&&!Reminders.notifications(this))notificationPermission();else if(reminder.isChecked()&&!Reminders.exact(this))toast("提醒已保存；尚未开启准时提醒权限，可能延迟");
  }catch(Exception e){toast(e instanceof NumberFormatException?"请填写有效分钟数":e.getMessage());}}));dialog.show();
 }
 void notificationPermission(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},101);else launch(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] results){super.onRequestPermissionsResult(r,p,results);if(r==WeatherLocation.REQUEST){weatherLocation.start(false);if(!WeatherLocation.permitted(this))toast("未获得定位权限，继续使用已设置地区");}Reminders.reschedule(this);render();}
 void launch(Intent i){try{startActivity(i);}catch(Exception e){toast("手机上没有可处理此操作的应用或设置");}}
 void openWeb(String url){if(url.startsWith(Api.CANVAS+"/"))launch(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}
 void clock(JSONObject task){String raw=task.optBoolean("reminder")?task.optString("reminderTime"):task.optString("plannedTime");if(raw.isEmpty()){pickTime("",s->openClock(task,s));return;}openClock(task,raw);}
 void openClock(JSONObject task,String value){LocalTime time=LocalTime.parse(value);String requested=task.optBoolean("reminder")?task.optString("reminderDate"):task.optString("due");ZonedDateTime now=ZonedDateTime.now();LocalDate next=now.toLocalDate();if(!time.isAfter(now.toLocalTime()))next=next.plusDays(1);
  Runnable send=()->{Intent i=new Intent(AlarmClock.ACTION_SET_ALARM).putExtra(AlarmClock.EXTRA_HOUR,time.getHour()).putExtra(AlarmClock.EXTRA_MINUTES,time.getMinute()).putExtra(AlarmClock.EXTRA_MESSAGE,task.optString("title","saber喵提醒")).putExtra(AlarmClock.EXTRA_SKIP_UI,false);launch(i);};
  if(!requested.isEmpty()&&(!requested.equals(next.toString())||!now.getOffset().equals(ZoneOffset.ofHours(8))))new UiDialog.Builder(this).setTitle("请在手机时钟核对日期").setMessage("这件事安排在 "+requested+"。标准闹钟接口只支持时分，不能直接传入年月日；手机时钟可能按下一次 "+value+" 创建闹钟。若要按指定日期提醒，请用saber喵提醒。").setPositiveButton("仍打开时钟",(a,b)->send.run()).setNegativeButton("取消",null).show();else {toast("请在手机时钟核对闹钟；此闹钟独立管理");send.run();}
 }
