 void secretDialog(String key,String label){LinearLayout form=column();form.setPadding(dp(18),0,dp(18),0);form.addView(text("凭证在本机加密保存，仅发送给对应官方服务。留空保留原值。",14));EditText input=field(form,label,"");input.setInputType(129);input.setSingleLine();new UiDialog.Builder(this).setTitle(label).setView(form).setPositiveButton("保存",(d,w)->{try{String value=input.getText().toString().trim();if(!value.isEmpty()){if(value.contains("\n")||value.contains("\r")||value.length()>4096)throw new Exception("凭证格式异常");Secrets.set(this,key,value);}prefs.edit().remove("canvasSuccessDay").apply();prefs.edit().remove("canvasAttempt").remove("canvasSuccessMillis").apply();CanvasAuto.watch(this);render();toast("配置已保存");}catch(Exception e){toast("凭证保存失败，请重试");}}).setNeutralButton("移除凭证",(d,w)->{try{Secrets.set(this,key,"");CanvasJob.ensure(this);render();}catch(Exception ignored){}}).setNegativeButton("取消",null).show();}
 void modelDialog(){EditText e=new EditText(this);e.setSingleLine();e.setText(prefs.getString("model","deepseek-flash"));new UiDialog.Builder(this).setTitle("DeepSeek 模型 ID").setView(e).setPositiveButton("保存",(d,w)->{String s=e.getText().toString().trim();if(s.matches("[a-zA-Z0-9._-]{1,100}"))prefs.edit().putString("model",s).apply();render();}).setNegativeButton("取消",null).show();}
