 void learnedMemory(){LinearLayout form=column();form.setPadding(dp(18),0,dp(18),0);form.addView(text("助手从你说过的话逐渐积累观察，不需要预设。单次记录标为待观察，多次不同表述支持同一内容时标为多次提及。记录会在后续对话中帮助建议，不代表模型被重新训练。",14));CheckBox learn=new CheckBox(this);learn.setText("从后续对话自动学习");learn.setChecked(prefs.getBoolean("memoryLearn",true));learn.setOnCheckedChangeListener((v,b)->prefs.edit().putBoolean("memoryLearn",b).putLong("memoryEpoch",prefs.getLong("memoryEpoch",0)+1).apply());form.addView(learn);CheckBox use=new CheckBox(this);use.setText("回答时使用积累的记忆");use.setChecked(prefs.getBoolean("memoryUse",true));use.setOnCheckedChangeListener((v,b)->prefs.edit().putBoolean("memoryUse",b).apply());form.addView(use);form.addView(text(LearnedMemory.behavior(TaskStore.load(this),Instant.now()),13));JSONArray a=learned();if(a.length()==0)form.addView(text("还没有观察记录。正常聊天即可，例如聊作息、学习感受或计划；有依据时才会记录。",15));AlertDialog[] parent=new AlertDialog[1];for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;form.addView(text(m.optString("topic")+" · "+m.optString("level"),17));form.addView(text(m.optString("value"),15));StringBuilder proof=new StringBuilder("依据：");JSONArray ps=m.optJSONArray("proofs");if(ps!=null)for(int j=0;j<ps.length();j++){JSONObject e=ps.optJSONObject(j);proof.append("\n").append(e.optString("date")).append(" “").append(e.optString("quote")).append("”");}form.addView(text(proof.toString(),12));String topic=m.optString("topic");form.addView(button("纠正 / 删除这条",()->{parent[0].dismiss();editLearned(topic);}));}form.addView(button("手动补充个人说明（可选）",()->{parent[0].dismiss();memory(null);}));form.addView(button("清空积累的记忆",()->new UiDialog.Builder(this).setMessage("清空观察记录？清空后新对话仍可继续学习，也可以关闭自动学习。").setPositiveButton("清空",(d,w)->{prefs.edit().remove("learnedMemory").putLong("memoryEpoch",prefs.getLong("memoryEpoch",0)+1).apply();parent[0].dismiss();learnedMemory();}).setNegativeButton("取消",null).show()));ScrollView sc=new ScrollView(this);sc.addView(form);parent[0]=new UiDialog.Builder(this).setTitle("逐渐了解你").setView(sc).setPositiveButton("关闭",null).create();parent[0].show();}
 void editLearned(String topic){JSONArray list=learned();JSONObject found=null;for(int i=0;i<list.length();i++)if(list.optJSONObject(i).optString("topic").equals(topic))found=list.optJSONObject(i);if(found==null)return;EditText value=new EditText(this);value.setText(found.optString("value"));value.setMinLines(3);new UiDialog.Builder(this).setTitle(topic).setView(value).setPositiveButton("纠正并固定",(d,w)->{String text=value.getText().toString().trim();if(text.isEmpty()||text.length()>300){toast("请填写 1–300 字");return;}try{JSONArray current=learned();for(int i=0;i<current.length();i++){JSONObject m=current.getJSONObject(i);if(m.optString("topic").equals(topic))m.put("value",text).put("locked",true).put("level","用户纠正").put("updated",LocalDate.now(Schedule.ZONE).toString()).put("proofs",new JSONArray());}prefs.edit().putString("learnedMemory",current.toString()).putLong("memoryEpoch",prefs.getLong("memoryEpoch",0)+1).apply();learnedMemory();}catch(Exception e){toast("记忆保存失败");}}).setNeutralButton("删除",(d,w)->{JSONArray current=learned(),next=new JSONArray();for(int i=0;i<current.length();i++)if(!current.optJSONObject(i).optString("topic").equals(topic))next.put(current.optJSONObject(i));prefs.edit().putString("learnedMemory",next.toString()).putLong("memoryEpoch",prefs.getLong("memoryEpoch",0)+1).apply();learnedMemory();}).setNegativeButton("取消",null).show();}
 void memory(String seed){LinearLayout form=column();form.setPadding(dp(18),0,dp(18),0);form.addView(text("记下偏好、作息和长期目标。发送给 AI 时会携带这些内容；可随时修改或清空，不会自动保存猜测。",14));String old=prefs.getString("memory","");EditText e=field(form,"个人记忆",seed==null?old:old+"\n"+seed);e.setMinLines(5);e.setMaxLines(12);ScrollView sc=new ScrollView(this);sc.addView(form);new UiDialog.Builder(this).setTitle("个人记忆").setView(sc).setPositiveButton("保存",(d,w)->{String s=e.getText().toString();if(s.length()>5000){toast("记忆最多 5000 字，请精简");return;}prefs.edit().putString("memory",s).apply();toast("个人记忆已保存");}).setNeutralButton("清空",(d,w)->{prefs.edit().remove("memory").apply();toast("个人记忆已清空");}).setNegativeButton("取消",null).show();}
 void syncCanvas(){if(busy)return;if(!Secrets.has(this,"canvas")){secretDialog("canvas","Canvas 个人访问令牌");return;}busy=true;status="正在同步 Canvas…";render();worker.execute(()->{try{int count=CanvasSync.run(getApplicationContext(),()->Thread.currentThread().isInterrupted());runOnUiThread(()->{if(isDestroyed())return;load();status="Canvas 同步完成：检查 "+count+" 项作业";busy=false;render();CanvasJob.ensure(this);});}catch(Exception e){prefs.edit().putString("canvasError",friendly(e)).apply();runOnUiThread(()->{if(isDestroyed())return;busy=false;status="同步未完成："+friendly(e);render();});}});}
 void chooseTerm(){try{JSONArray options=new JSONArray(prefs.getString("canvasTerms","[]"));SchoolCalendar.Period period=CanvasSync.period(this);if(period==null){calendarSettings();return;}if(options.length()==0){toast("先点立即同步，读取你可访问的学校学期列表");return;}String[] labels=new String[options.length()];for(int i=0;i<labels.length;i++)labels[i]=options.getJSONObject(i).optString("name")+" · ID "+options.getJSONObject(i).optString("id");new UiDialog.Builder(this).setTitle("对应 "+period.name+" 的 Canvas 学期").setItems(labels,(d,w)->{try{JSONObject term=options.getJSONObject(w);prefs.edit().putString("canvasTerm",term.getString("id")).putString("canvasTermName",term.optString("name")).putString("canvasTermPeriod",period.key).remove("canvasSuccessDay").apply();syncCanvas();}catch(Exception e){toast("学期选择失败");}}).setNegativeButton("取消",null).show();}catch(Exception e){toast("请重新读取学期列表");}}
 void calendarSettings(){SchoolCalendar.Period period=CanvasSync.period(this);LinearLayout form=column();form.setPadding(dp(18),0,dp(18),0);form.addView(text("依据同济官网校历。两个常规学期之间按你的习惯作为小学期；这不是学校统一的小学期命名。已核对到 2027-02-21，之后需补充新校历。",14));form.addView(button("打开官方校历",()->launch(new Intent(Intent.ACTION_VIEW,Uri.parse(SchoolCalendar.SOURCE)))));EditText name=field(form,"学期名称",period==null?"":period.name);final LocalDate[] range={period==null?LocalDate.now(Schedule.ZONE):period.start,period==null?LocalDate.now(Schedule.ZONE).plusMonths(4):period.end};Button start=button("开始："+range[0],()->{}),end=button("结束："+range[1],()->{});start.setOnClickListener(v->pickDate(range[0],d->{range[0]=d;start.setText("开始："+d);}));end.setOnClickListener(v->pickDate(range[1],d->{range[1]=d;end.setText("结束："+d);}));form.addView(start);form.addView(end);CheckBox gap=new CheckBox(this);gap.setText("小学期：仅保留范围内截止的作业");gap.setChecked(period!=null&&period.gap);form.addView(gap);ScrollView sc=new ScrollView(this);sc.addView(form);AlertDialog dialog=new UiDialog.Builder(this).setTitle("校历日期").setView(sc).setPositiveButton("保存",null).setNeutralButton("恢复官方日期",(a,b)->{prefs.edit().remove("periodName").remove("periodStart").remove("periodEnd").remove("periodGap").remove("canvasTermPeriod").remove("canvasSuccessDay").apply();CanvasSync.archivePrevious(this);load();render();}).setNegativeButton("取消",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{LocalDate now=LocalDate.now(Schedule.ZONE);if(range[1].isBefore(range[0])||now.isBefore(range[0])||now.isAfter(range[1])||name.getText().toString().trim().isEmpty()){toast("请填写包含今天的有效学期范围和名称");return;}prefs.edit().putString("periodName",name.getText().toString()).putString("periodStart",range[0].toString()).putString("periodEnd",range[1].toString()).putBoolean("periodGap",gap.isChecked()).remove("canvasTermPeriod").remove("canvasSuccessDay").apply();CanvasSync.archivePrevious(this);load();dialog.dismiss();render();CanvasJob.ensure(this);}));dialog.show();}
 void archivedTasks(){StringBuilder b=new StringBuilder();for(int i=0;i<tasks.length();i++){JSONObject t=tasks.optJSONObject(i);if(t!=null&&t.optBoolean("archived"))b.append("ID ").append(t.optString("id")).append(" | ").append(t.optString("title")).append(" | 备注 ").append(t.optString("notes")).append(t.optBoolean("done")?" ✓":"").append("\n").append(t.optString("notes")).append("\n\n");}TextView t=text(b.length()==0?"暂无归档记录":b.toString(),15);t.setTextIsSelectable(true);ScrollView sc=new ScrollView(this);sc.setPadding(dp(18),0,dp(18),0);sc.addView(t);new UiDialog.Builder(this).setTitle("旧学期归档 · 只读").setView(sc).setPositiveButton("关闭",null).show();}
 void changelog(){new UiDialog.Builder(this).setTitle("saber喵 · 1.1.5").setMessage("• 修复小组件空白处点击进入应用。\n• 本周改为未来7天，包含今天到第7天。\n• 未设日期及逾期未完成待办继续保留。") .setPositiveButton("知道了",(d,w)->prefs.edit().putInt("seenVersion",11).apply()).show();}

 String friendly(Exception e){if(e instanceof java.net.SocketTimeoutException)return "连接超时，请检查网络后重试";if(e instanceof java.net.UnknownHostException)return "无法连接服务器，请检查网络";if(e instanceof JSONException)return "接口返回内容不符合预期";return e.getMessage()==null?"连接失败，请重试":e.getMessage();}
